import { NextRequest, NextResponse } from "next/server";
import { limitOrbitRequest } from "@/lib/aura/durable-limit";
import { getAuraConfig } from "@/lib/aura/config";
import { synthesizeSpeech, SPEECH_LIMITS } from "@/lib/aura/speech";
import { getSiteContent } from "@/lib/site-content";
import { publicApiGate } from "@/lib/public-gate";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const NO_STORE = { "Cache-Control": "no-store" };

/**
 * POST { text } → audio (WAV or MP3) of one passage of an Orbit reply, generated by Workers AI
 * MeloTTS. Enforced here: the CMS switches (spoken replies, cloud voice), maintenance gate,
 * rate limit and text length. Credentials stay on the server; nothing is stored or logged.
 */
export async function POST(req: NextRequest) {
  const closed = await publicApiGate("Orbit's voice");
  if (closed) return closed;
  const site = await getSiteContent();
  if (site.ai?.voicePlayback === false || site.ai?.cloudVoice === false) {
    return NextResponse.json({ error: "Orbit's cloud voice is not enabled.", code: "disabled" }, { status: 403, headers: NO_STORE });
  }

  const limit = await limitOrbitRequest(req.headers, "speech", SPEECH_LIMITS.perMinute, 60 * 1000, "degrade");
  if (!limit.allowed) {
    return NextResponse.json(
      { error: "Too many voice requests. Please wait a moment.", code: "busy" },
      { status: 429, headers: { ...NO_STORE, "Retry-After": String(limit.resetInSeconds) } }
    );
  }

  if (Number(req.headers.get("content-length") || 0) > 8 * 1024) {
    return NextResponse.json({ error: "This passage is too long to read in one request.", code: "bad-request" }, { status: 413, headers: NO_STORE });
  }
  let body: { text?: unknown } | null = null;
  try {
    body = (await req.json()) as { text?: unknown };
  } catch {
    body = null;
  }

  const config = getAuraConfig();
  const result = await synthesizeSpeech(body?.text, { accountId: config.accountId, apiToken: config.apiToken });
  if (!result.ok) {
    const headers: Record<string, string> = { ...NO_STORE };
    if (result.status === 429) headers["Retry-After"] = result.code === "quota" ? "3600" : "30";
    return NextResponse.json({ error: result.error, code: result.code }, { status: result.status, headers });
  }
  return new Response(result.audio as unknown as BodyInit, {
    status: 200,
    headers: {
      ...NO_STORE,
      "Content-Type": result.contentType,
      "Content-Length": String(result.audio.byteLength),
      "X-Content-Type-Options": "nosniff",
    },
  });
}
